SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, COUNT_IF(status = 'CLOSED') AS closed_events, ROUND(AVG(balance), 2) AS avg_balance, APPROX_PERCENTILE(balance, 0.95) AS balance_p95 FROM accounts GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', opened_date), DATE_TRUNC('QUARTER', opened_date)), (DATE_TRUNC('WEEK', opened_date)), ()) HAVING COUNT_IF(status = 'CLOSED') > 1 ORDER BY avg_balance DESC NULLS FIRST;
